script:
existe = frappe.db.exists(
    "Asignacion Unidad Operativa",
    {
        "usuario": doc.usuario,
        "unidad_operativa": doc.unidad_operativa,
        "cargo": doc.cargo,
        "name": ("!=", doc.name)
    }
)

if existe:
    frappe.throw(
        f"""
Ya existe una asignación para:

Usuario: {doc.usuario}

Unidad Operativa: {doc.unidad_operativa}

Cargo: {doc.cargo}
"""
    )
    
if doc.fecha_inicio and doc.fecha_fin:
    if doc.fecha_inicio > doc.fecha_fin:
        frappe.throw("La Fecha Inicio no puede ser mayor que la Fecha Fin.")
        
        
enabled = frappe.db.get_value("User", doc.usuario, "enabled")

if not enabled:
    frappe.throw("El usuario se encuentra deshabilitado.")

old_doc = doc.get_doc_before_save()

if old_doc:

    if old_doc.estado == "Aprobado":

        frappe.throw(
            "Este recibo ya fue aprobado dentro de una Planilla y no puede modificarse."
        )

    if old_doc.estado == "Anulado":

        frappe.throw(
            "Este recibo está anulado y no puede modificarse."
        )


fecha_recibo = frappe.utils.getdate(doc.fecha)

# -----------------------------------
# Usuario Captura
# -----------------------------------

usuario_actual = frappe.session.user
doc.usuario_captura = usuario_actual


# -----------------------------------
# Buscar Calendario
# -----------------------------------

calendarios = frappe.get_all(
    "Calendario",
    filters={
        "estado": "Abierto"
    },
    fields=[
        "name",
        "fecha_inicial",
        "fecha_final"
    ]
)

for cal in calendarios:

    if (
        cal.fecha_inicial
        and cal.fecha_final
        and cal.fecha_inicial <= fecha_recibo <= cal.fecha_final
    ):
        doc.calendario = cal.name
        break

if not doc.calendario:
    frappe.throw(
        f"No existe un Calendario IFI abierto para la fecha {doc.fecha}"
    )

# -----------------------------------
# Calcular Entrega
# -----------------------------------

calendario = frappe.get_doc(
    "Calendario",
    doc.calendario
)

entrega_encontrada = 0

entregas = sorted(
    calendario.get("entregas") or [],
    key=lambda x: x.entrega
)

for fila in entregas:

    if fila.estado != "Abierto":
        continue

    if fila.fecha and fecha_recibo <= fila.fecha:

        entrega_encontrada = fila.entrega
        break

if not entrega_encontrada:

    frappe.throw(
        f"No se encontró una entrega válida para la fecha {doc.fecha}"
    )

doc.entrega = entrega_encontrada

# -----------------------------------
# Validar Cuenta Recaudo
# -----------------------------------

if doc.forma_pago in [
    "Transferencia",
    "PSE",
    "Wompi"
]:

    if not doc.banco_recaudo:

        frappe.throw(
            "Debe seleccionar el Banco de Recaudo."
        )

total = 0

for fila in (doc.conceptos_de_donacion or []):
    total += (fila.valor or 0)

doc.total = total

if doc.forma_de_pago in [
    "Transferencia",
    "PSE",
    "Wompi"
]:

    if not doc.banco_recaudo:
        frappe.throw(
            "Debe seleccionar el banco de Recaudo."
        )

usados = set()

for fila in (doc.donaciones or []):

    if fila.donacion in usados:

        frappe.throw(
            f"La donación {fila.donacion} está repetida en la planilla."
        )

    usados.add(fila.donacion)

unidad = frappe.form_dict.get("unidad_organizacional")

visitadas = set()

while unidad and unidad not in visitadas:

    visitadas.add(unidad)

    bancos = frappe.get_all(
        "Bank Account",
        filters={
            "custom_unidad_organizacional": unidad
        },
        pluck="name"
    )

    if bancos:
        frappe.response["message"] = bancos
        break

    unidad = frappe.db.get_value(
        "Unidad Organizacional",
        unidad,
        "parent_unidad_organizacional"
    )

else:
    frappe.response["message"] = []
